// Native document fixes preserve real mutation targets and option matching.
const queueMutationRecord = (observer, record) => {
  observer.records.push(record);
  // A private host wrapper can enqueue one public microtask at mutation time,
  // preserving ordering relative to author-created Promise jobs.
  if (typeof observer.__pircOnMutationQueued === 'function') {
    observer.__pircOnMutationQueued();
    return;
  }
  if (!observer.scheduled) {
    observer.scheduled = true;
    Promise.resolve().then(() => {
      observer.scheduled = false;
      observer.callback(observer.records.splice(0), observer);
    });
  }
};

